-- TABELA movimentoitem

DROP TABLE IF EXISTS `movimentoitem`;
CREATE TABLE `movimentoitem` (
  `id` int NOT NULL AUTO_INCREMENT,
  `idEmpresa` int NOT NULL,
  `ControleMovimento` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `ServProd` int NOT NULL,
  `Descricao` varchar(300) COLLATE utf8mb4_general_ci NOT NULL,
  `Qtd` int NOT NULL,
  `Valor` decimal(10,2) NOT NULL,
  `TotalItem` decimal(10,2) NOT NULL,
  `DataAlt` datetime NOT NULL,
  `ValorCusto` decimal(10,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

